RFDETR_THRESHOLDS = (0.01, 0.03, 0.05, 0.1, 0.2, 0.3, 0.5, 0.7)


def rfdetr_checkpoint(run_dir) -> Path:
    "Return `<run_dir>/checkpoints/last_ema.pth`, the checkpoint to evaluate; raises `FileNotFoundError` when it is missing."
    p = Path(run_dir) / 'checkpoints' / 'last_ema.pth'
    if not p.exists():
        raise FileNotFoundError(f'{p} not found: {run_dir} has no RF-DETR checkpoint (train with model.source=rfdetr)')
    return p


def rfdetr_loader(ckpt):
    "Load a trained `RFDETR` model from `ckpt`; the only loading call that imports `rfdetr` (raises `ImportError(INSTALL_HINT)` without it)."
    try:
        from rfdetr import RFDETR
    except ImportError as e:
        raise ImportError(INSTALL_HINT) from e
    return RFDETR.from_checkpoint(str(ckpt))


class RFDETRPredictor:
    """A loaded RF-DETR model plus the rule that turns its detections into a `(num_classes, H, W)` score map.

    `model` needs `predict(image, threshold=...)` returning `supervision.Detections`-like objects.
    """
    def __init__(self, model, num_classes: int, train_size: Optional[int] = None):
        self.model, self.num_classes, self.train_size = model, int(num_classes), train_size   # train_size: patch side it was trained on

    def detections(self, image, threshold: float = 0.0):
        "RF-DETR detections of one image (an `(H, W[, C])` array or a PIL image) scoring at least `threshold`."
        if isinstance(image, np.ndarray):
            from PIL import Image
            image = Image.fromarray(image)
        return self.model.predict(image, threshold=threshold)

    def stack(self, dets, shape, threshold: float = 0.0):
        "Rasterise `dets` to `(num_classes, H, W)` float32: best score per class and pixel among detections scoring at least `threshold`."
        return detections_to_semantic(dets, shape=tuple(shape), class_ids=range(self.num_classes), first_class_id=0,
                                      output='stack', threshold=threshold)

    def __call__(self, image, threshold: float = 0.5):
        "Score map of one image at `threshold`; `> 0` is the binary prediction."
        return self.stack(self.detections(image, threshold), np.asarray(image).shape[:2], threshold)


def load_rfdetr_predictor(run_dir, num_classes: Optional[int] = None, loader: Optional[Callable] = None) -> RFDETRPredictor:
    """Load `checkpoints/last_ema.pth` of an RF-DETR run as an `RFDETRPredictor`.

    `num_classes` defaults to the number of `data.class_names` in the run's `.hydra/config.yaml` (1 when there are none).
    `loader(ckpt)` returns the model; the default is `rfdetr_loader` (tests pass a stub).
    """
    ckpt = rfdetr_checkpoint(run_dir)
    if num_classes is None:
        from omegaconf import OmegaConf
        cfg_path = Path(run_dir) / '.hydra' / 'config.yaml'
        names = OmegaConf.load(cfg_path).data.get('class_names', None) if cfg_path.exists() else None
        num_classes = len(names) if names else 1
    train_size = None
    cfg_path = Path(run_dir) / '.hydra' / 'config.yaml'
    if cfg_path.exists():
        from omegaconf import OmegaConf
        train_size = OmegaConf.load(cfg_path).get('train', {}).get('crop_size', None)
    return RFDETRPredictor((loader or rfdetr_loader)(ckpt), num_classes, train_size)


